    private void updateFrame() {
        final Template mTemplate = this.mTemplate;
        if (mTemplate != null && mTemplate.isVideoSquare() && this.mTemplate.getIpad_type() != IpadType.RECT.ordinal() && this.mTemplate.getIpad_type() != IpadType.ROUND_RECT.ordinal() && this.mTemplate.getIpad_type() != IpadType.CASSET_IMG_BLUR.ordinal()) {
            if (this.mTemplate.getIpad_type() != IpadType.CASSET.ordinal()) {
                if (!this.mIsPlaying) {
                    final int round = Math.round(this.trackViewEntity.getCurrent_cursur_position() / 1000.0f * 25.0f);
                    final int n = 1;
                    int max = Math.max(n, round);
                    final int min = Math.min(this.mTemplate.getDuration_video_media() * 25, this.trackViewEntity.getDuration() * 25);
                    if (max > min) {
                        max = (max - 1) % min + n;
                    }
                    final int n2 = 10;
                    final String s = ".jpg";
                    String child;
                    if (max < n2) {
                        child = "frame_000" + max + s;
                    }
                    else if (max < 100) {
                        child = "frame_00" + max + s;
                    }
                    else if (max < 1000) {
                        child = "frame_0" + max + s;
                    }
                    else {
                        child = "frame_" + max + s;
                    }
                    this.isOnScroll = (n != 0);
                    this.updateSquareBitmap(new File(this.mTemplate.getFolder_template() + "/VideoFrame", child).getAbsolutePath());
                }
            }
        }
    }
    
